import openpyxl
wb=openpyxl.load_workbook('/root/output/rar_result.xlsx')
ws=wb['Gold price']
max_row=ws.max_row
for r in range(2, max_row+1):
    if r==2:
        ws.cell(r,3).value=None
    else:
        ws.cell(r,3).value=f"=IF(OR(B{r}=\"\",B{r-1}=\"\"),\"\",LN(B{r}/B{r-1})*100)"
    if r>=4:
        ws.cell(r,4).value=f"=IF(COUNTA(C{r-2}:C{r})=3,STDEV.S(C{r-2}:C{r}),\"\")"
    else:
        ws.cell(r,4).value=None
    if r>=13:
        ws.cell(r,5).value=f"=IF(COUNTA(C{r-11}:C{r})=12,STDEV.S(C{r-11}:C{r}),\"\")"
    else:
        ws.cell(r,5).value=None

wb.save('/root/output/rar_result.xlsx')
print('fixed formulas')
